entries[28591] = { ["name"] = "Fläschchen des reinen Todes", ["text"] = "Wirken in 25 sek.\nReagenzien:\nTeufelslotus , Manadistel (3), Alptraumranke (7), Kristallphiole\n(2)\n65\nBenutzen: Erhöht die Schatten-, Feuer- und Frostzaubermacht 1 Stunde lang um 80. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
