entries[29572] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 250% Waffenschaden und verwundet das Ziel, verringert außerdem die Wirksamkeit jeglicher Heilung 5 Sek. lang um 50%." }
entries[29573] = { ["name"] = "Wirbelwind", ["text"] = "Kanalisiert (Wirken in 2 sek.)\nGreift in der Nähe befindliche Feinde mit einem Wirbel aus Stahl an, der 2 Sek. lang anhält und normalen Schaden plus 300 verursacht." }
entries[29574] = { ["name"] = "Verwunden", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 15 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
entries[29575] = { ["name"] = "Schießen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt auf den Feind und fügt körperlichen Schaden zu." }
entries[29576] = { ["name"] = "Mehrfachschuss", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nFeuert eine Salve von Geschossen auf einen Feind und seine nächsten Verbündeten ab, fügt normalen Schaden plus 3150 to 3850 zu, wirkt auf bis zu 3 Ziele." }
entries[29577] = { ["name"] = "Hufschlag", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nSchlägt einen Feind und fügt erhöhten Nahkampfschaden zu." }
entries[29578] = { ["name"] = "Verwunden", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 15 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
entries[29579] = { ["name"] = "Dynamit werfen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nFügt allen Feinden in einem ausgewählten Gebiet 425 to 575 Feuerschaden zu." }
entries[29580] = { ["name"] = "Heilung", ["text"] = "215 Mana 40 Meter Reichweite\nWirken in 3.5 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[29581] = { ["name"] = "Fausthieb", ["text"] = "Nahkampfreichweite\nSofort\nDeckt das Ziel mit Schlägen ein. Fügt Nahkampfschaden zu." }
entries[29582] = { ["name"] = "Werfen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nWirft eine Waffe nach einem Feind und fügt körperlichen Schaden zu." }
entries[29583] = { ["name"] = "Durchbohren", ["text"] = "5 - 30 Meter Reichweite\nSofort\nFügt einem Feind 9 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
entries[29584] = { ["name"] = "Demoralisierender Ruf", ["text"] = "Sofort\nVerringert die Nahkampfangriffskraft von in der Nähe befindlichen Feinden 20 Sek. lang um 300." }
entries[29585] = { ["name"] = "Aufwärtshaken", ["text"] = "10 Meter Reichweite\nSofort\nFügt einem Feind normalen Schaden plus 50 zu und stößt ihn zurück." }
entries[29586] = { ["name"] = "Tritt", ["text"] = "Nahkampfreichweite\nSofort\nTritt einen Feind, fügt ihm 675 to 825 Schaden zu und unterbricht 5 Sek. lang den gewirkten Zauber." }
entries[29587] = { ["name"] = "Schattenverjüngung", ["text"] = "300 Mana 40 Meter Reichweite\nSofort\nHeilt einen Verbündeten 12 Sek. lang alle 3 Sek." }
entries[29588] = { ["name"] = "Verteidigungstaktiken", ["text"] = "Ihr behaltet bis zu 66% Eurer Wut, wenn Ihr von der Verteidigungshaltung in eine andere Haltung wechselt." }
