entries[29592] = { ["name"] = "Präzision", ["text"] = "Erhöht die Trefferchance Eurer Angriffe um 3% sowie den Schaden Eurer automatischen Angriffe um 40%." }
entries[29593] = { ["name"] = "Verteidigungsbastion", ["text"] = "Benötigt Verteidigungshaltung\nIn der Verteidigungshaltung wird Eure Chance, kritische Nahkampftreffer zu erleiden, um 3% verringert. Zudem besteht, wenn Ihr einen Angriff blockt, pariert oder ihm ausweicht, eine Chance von 10%, dass Ihr wütend werdet und Euer verursachter körperlicher Schaden 12 Sek. lang um 5% erhöht wird.\n(Procchance: 10%)" }
entries[29594] = { ["name"] = "Verteidigungsbastion", ["text"] = "Benötigt Verteidigungshaltung\nIn der Verteidigungshaltung wird Eure Chance, kritische Nahkampftreffer zu erleiden, um 6% verringert. Zudem besteht, wenn Ihr einen Angriff blockt, pariert oder ihm ausweicht, eine Chance von 20%, dass Ihr wütend werdet und Euer verursachter körperlicher Schaden 12 Sek. lang um 10% erhöht wird.\n(Procchance: 20%)" }
entries[29598] = { ["name"] = "Schildbeherrschung", ["text"] = "Verringert die Abklingzeit Eurer Fähigkeit 'Schildblock' um 10 Sek. und die Abklingzeit Eurer Fähigkeit 'Schildwall' um 60 Sek. Zudem verringert Eure Fähigkeit 'Schildblock' zusätzlich 6 Sek. lang den erlittenen Magieschaden um 7%." }
entries[29601] = { ["name"] = "Erleuchtung", ["text"] = "Sofort\nJeder Zauber, der innerhalb von 20 Sek. gewirkt wird, gewährt einen stapelbaren Bonus von 52 Willenskraft. Endet nach 20 Sek.. Fähigkeiten, die kein Mana verbrauchen, lösen dieses Schmuckstück nicht aus." }
entries[29602] = { ["name"] = "Jom Gabbar", ["text"] = "Sofort\nErhöht die Angriffskraft um 65 und alle 2 Sek. um zusätzliche 65. Hält 20 Sek. lang an." }
